#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int *data;
    int size;
    int capacity;
} IntSet;

void intset_init(IntSet *set) {
    set->capacity = 4;
    set->size = 0;
    set->data = (int*)malloc(set->capacity * sizeof(int));
}

void intset_free(IntSet *set) {
    free(set->data);
}

bool intset_contains(IntSet *set, int val) {
    // binary search since data is sorted
    int left = 0, right = set->size - 1;
    while (left <= right) {
        int mid = left + (right - left)/2;
        if (set->data[mid] == val) return true;
        else if (set->data[mid] < val) left = mid + 1;
        else right = mid - 1;
    }
    return false;
}

void intset_add(IntSet *set, int val) {
    // insert val into sorted array if not present
    if (intset_contains(set, val)) return;
    if (set->size == set->capacity) {
        set->capacity *= 2;
        set->data = (int*)realloc(set->data, set->capacity * sizeof(int));
    }
    // find position to insert
    int pos = 0;
    while (pos < set->size && set->data[pos] < val) pos++;
    for (int i = set->size; i > pos; i--) {
        set->data[i] = set->data[i-1];
    }
    set->data[pos] = val;
    set->size++;
}

bool canCross(int* stones, int stonesSize){
    if (stonesSize == 2) return stones[1] == 1;

    // Map stone position to index for quick lookup
    // Use binary search to find stone index by position
    // We'll keep an array of IntSet to store possible jump lengths that can reach each stone
    IntSet *dp = (IntSet*)malloc(stonesSize * sizeof(IntSet));
    for (int i = 0; i < stonesSize; i++) {
        intset_init(&dp[i]);
    }
    // The first stone can be reached with jump length 0 (start)
    intset_add(&dp[0], 0);

    for (int i = 0; i < stonesSize; i++) {
        IntSet *curSet = &dp[i];
        for (int j = 0; j < curSet->size; j++) {
            int k = curSet->data[j];
            // next jump can be k-1, k, k+1 but must be > 0
            for (int step = k - 1; step <= k + 1; step++) {
                if (step <= 0) continue;
                int nextPos = stones[i] + step;
                // binary search for nextPos in stones
                int left = i + 1, right = stonesSize - 1, mid;
                while (left <= right) {
                    mid = left + (right - left)/2;
                    if (stones[mid] == nextPos) {
                        intset_add(&dp[mid], step);
                        break;
                    } else if (stones[mid] < nextPos) {
                        left = mid + 1;
                    } else {
                        right = mid - 1;
                    }
                }
            }
        }
    }
    bool res = dp[stonesSize - 1].size > 0;
    for (int i = 0; i < stonesSize; i++) {
        intset_free(&dp[i]);
    }
    free(dp);
    return res;
}

